#include "parallel_letter_frequency.h"
#include <cassert>
#include <cctype>
#include <iostream>
#include <random>
#include <string>
#include <vector>

using parallel_letter_frequency::frequency;

int main() {
    // empty list
    assert(frequency({}).empty());

    // empty strings and whitespace only
    assert(frequency({"", "", " \t\n\r\v\f"}).empty());

    // non-letter bytes incl. high-bit chars must be ignored (unsigned char handling)
    std::string weird;
    for (int b = 0; b < 256; ++b) {
        if (!std::isalpha(static_cast<unsigned char>(b))) weird.push_back(static_cast<char>(b));
    }
    assert(frequency({weird}).empty());

    // mixed case and disjoint texts
    auto f = frequency({"aA zZ", "Bb", "", "ccc"});
    assert(f.size() == 4);
    assert(f['a'] == 2 && f['z'] == 2 && f['b'] == 2 && f['c'] == 3);
    assert(f.count('x') == 0);

    // randomized cross-check against sequential counting
    std::mt19937 rng(12345);
    std::uniform_int_distribution<int> len(0, 500);
    std::uniform_int_distribution<int> byte(0, 255);
    std::vector<std::string> texts;
    for (int i = 0; i < 300; ++i) {
        std::string s;
        int n = len(rng);
        for (int j = 0; j < n; ++j) s.push_back(static_cast<char>(byte(rng)));
        texts.push_back(std::move(s));
    }
    std::vector<std::string_view> views;
    for (auto const& s : texts) views.push_back(s);

    std::map<char, std::size_t> expected;
    for (auto const& s : views)
        for (unsigned char ch : s)
            if (std::isalpha(ch)) expected[static_cast<char>(std::tolower(ch))]++;

    auto got = frequency(views);
    assert(got == expected);

    // many identical small texts (chunking across many threads)
    std::vector<std::string_view> many(1000, "abbccc");
    auto m = frequency(many);
    assert(m['a'] == 1000 && m['b'] == 2000 && m['c'] == 3000);

    std::cout << "edge cases OK\n";
}
